import{_ as i,c as a,o as s,a6 as o}from"./chunks/framework.BY05barL.js";const r="/ucasal-ssoo-estudio/assets/15-jerarquia-archivos.CJTvIAyv.png",t="/ucasal-ssoo-estudio/assets/15-linux-filesystem.BAIIpHQx.png",l="/ucasal-ssoo-estudio/assets/16-archivos-bloques-caracteres.QN56o6-d.png",n="/ucasal-ssoo-estudio/assets/21-sistema-archivos.D2md9VhG.png",b=JSON.parse('{"title":"Sistemas de Archivos","description":"","frontmatter":{},"headers":[],"relativePath":"unidad1/sistemas-archivos.md","filePath":"unidad1/sistemas-archivos.md"}'),c={name:"unidad1/sistemas-archivos.md"};function d(h,e,u,m,p,v){return s(),a("div",null,[...e[0]||(e[0]=[o('<h1 id="sistemas-de-archivos" tabindex="-1">Sistemas de Archivos <a class="header-anchor" href="#sistemas-de-archivos" aria-label="Permalink to &quot;Sistemas de Archivos&quot;">​</a></h1><h2 id="directorio-raiz" tabindex="-1">Directorio Raíz <a class="header-anchor" href="#directorio-raiz" aria-label="Permalink to &quot;Directorio Raíz&quot;">​</a></h2><p>El directorio raíz es el directorio principal del sistema de archivos, que contiene todos los archivos y directorios del sistema.</p><h3 id="en-linux" tabindex="-1">En Linux <a class="header-anchor" href="#en-linux" aria-label="Permalink to &quot;En Linux&quot;">​</a></h3><ul><li>Representado por <code>/</code></li><li>Jerarquía única</li><li>Distinción entre mayúsculas y minúsculas</li><li>Todos los dispositivos se montan en esta jerarquía</li></ul><h3 id="en-windows" tabindex="-1">En Windows <a class="header-anchor" href="#en-windows" aria-label="Permalink to &quot;En Windows&quot;">​</a></h3><ul><li>Representado por <code>C:\\</code> (y otras letras para diferentes unidades)</li><li>Jerarquía múltiple</li><li>No distingue entre mayúsculas y minúsculas</li><li>Cada unidad tiene su propia jerarquía</li></ul><h2 id="jerarquia-de-archivos-en-linux" tabindex="-1">Jerarquía de archivos en Linux <a class="header-anchor" href="#jerarquia-de-archivos-en-linux" aria-label="Permalink to &quot;Jerarquía de archivos en Linux&quot;">​</a></h2><p><img src="'+r+'" alt="Jerarquía de archivos en Linux"></p><ul><li>(a) Antes de montarse, los archivos del CD-ROM no están disponibles</li><li>(b) Después de montarse, los archivos del CD-ROM están disponibles en <code>/mnt/cdrom</code></li></ul><p>La estructura de directorios en Linux sigue un estándar (Filesystem Hierarchy Standard) que define el propósito de cada directorio:</p><p><img src="'+t+'" alt="Sistema de archivos en Linux"></p><h2 id="tipos-de-archivos" tabindex="-1">Tipos de Archivos <a class="header-anchor" href="#tipos-de-archivos" aria-label="Permalink to &quot;Tipos de Archivos&quot;">​</a></h2><h3 id="archivos-de-bloques" tabindex="-1">Archivos de Bloques <a class="header-anchor" href="#archivos-de-bloques" aria-label="Permalink to &quot;Archivos de Bloques&quot;">​</a></h3><ul><li>Almacenan datos en bloques de tamaño fijo</li><li>Se accede a los bloques de forma aleatoria</li><li>Ejemplo: disco duro</li><li>Ejemplo en Linux: <code>/dev/sda</code></li></ul><h3 id="archivos-de-caracteres" tabindex="-1">Archivos de Caracteres <a class="header-anchor" href="#archivos-de-caracteres" aria-label="Permalink to &quot;Archivos de Caracteres&quot;">​</a></h3><ul><li>Almacenan datos en secuencia</li><li>Se accede a los datos de forma secuencial</li><li>Ejemplo: impresora</li><li>Ejemplo en Linux: <code>/dev/tty0</code></li></ul><p><img src="'+l+'" alt="Archivos de Bloques y Archivos de Caracteres"></p><h2 id="sistema-de-archivos" tabindex="-1">Sistema de Archivos <a class="header-anchor" href="#sistema-de-archivos" aria-label="Permalink to &quot;Sistema de Archivos&quot;">​</a></h2><p>Un sistema de archivos es una estructura de datos que:</p><ul><li>Almacena archivos y directorios</li><li>Permite acceder a los archivos y directorios</li><li>Gestiona el espacio en disco</li><li>Proporciona mecanismos de seguridad y control de acceso</li></ul><p><img src="'+n+'" alt="Sistema de Archivos"></p><h2 id="componentes-de-un-sistema-de-archivos" tabindex="-1">Componentes de un Sistema de Archivos <a class="header-anchor" href="#componentes-de-un-sistema-de-archivos" aria-label="Permalink to &quot;Componentes de un Sistema de Archivos&quot;">​</a></h2><ol><li><strong>Bootblock</strong>: Contiene el código para arrancar el sistema operativo</li><li><strong>Superblock</strong>: Contiene información sobre el sistema de archivos (tamaño, estado, etc.)</li><li><strong>Inodos</strong>: Contienen metadatos de los archivos (permisos, propietario, ubicación de los datos, etc.)</li><li><strong>Bloques de datos</strong>: Almacenan el contenido de los archivos</li></ol><h2 id="operaciones-comunes-en-sistemas-de-archivos" tabindex="-1">Operaciones comunes en Sistemas de Archivos <a class="header-anchor" href="#operaciones-comunes-en-sistemas-de-archivos" aria-label="Permalink to &quot;Operaciones comunes en Sistemas de Archivos&quot;">​</a></h2><ul><li>Crear un archivo</li><li>Eliminar un archivo</li><li>Abrir un archivo</li><li>Cerrar un archivo</li><li>Leer de un archivo</li><li>Escribir en un archivo</li><li>Cambiar atributos de un archivo</li><li>Crear un directorio</li><li>Eliminar un directorio</li><li>Listar el contenido de un directorio</li></ul>',26)])])}const A=i(c,[["render",d]]);export{b as __pageData,A as default};
